// Hive is our local database — this import gives us access to all
// Hive annotations and the HiveObject base class
import 'package:hive_flutter/hive_flutter.dart';

// This file is automatically generated by build_runner based on the
// Hive annotations below. Don't edit it manually — always regenerate
// it by running 'dart run build_runner build --delete-conflicting-outputs'
part 'sound_button.g.dart';

// @HiveType marks this class as a Hive-storable object
// typeId must be unique across all Hive models in the app
@HiveType(typeId: 0)

// HiveObject gives us helper methods like save() and delete()
// directly on each SoundButton instance
class SoundButton extends HiveObject {
  // Each @HiveField annotation assigns a unique index to each property
  // These indices must never change once data has been saved to disk —
  // changing them would corrupt existing saved data

  @HiveField(0)
  late String id; // Unique identifier for each button

  @HiveField(1)
  late String label; // The name shown on the button face

  @HiveField(2)
  late String audioFilePath; // Where the audio file lives on the device

  @HiveField(3)
  late int color; // Stored as an integer — Flutter colors are just numbers

  @HiveField(4)
  late DateTime createdAt; // When the button was created, used for sorting

  @HiveField(5)
  String? categoryId; // Null for now — used later when we add categories

  @HiveField(6)
  bool isFavorite; // For a favorites feature later

  // Stores the button's position in the grid so the user's custom
  // order is remembered between sessions. Nullable so that existing
  // saved buttons without this field don't cause a crash — we fall
  // back to 0 if the value was never set
  @HiveField(7)
  int? order;

  SoundButton({
    required this.id,
    required this.label,
    required this.audioFilePath,
    required this.color,
    required this.createdAt,
    this.categoryId,
    this.isFavorite = false,
    this.order, // Defaults to null, handled safely wherever order is used
  });
}